import { applySelectChanges, compareOptions } from "./utils.js";
export default {
    tag: "f-relation",
    jsImport: "lume_cms/components/f-relation.js",
    async init(field, cmsContent) {
        if (field.options?.length) {
            return;
        }
        const collection = cmsContent.collections[field.collection];
        if (!collection) {
            throw new Error(`Collection '${field.collection}' not found for relation field '${field.name}'`);
        }
        const createOption = field.option ??
            (({ label, name }) => ({
                label,
                value: name,
            }));
        field.options = (await Array.fromAsync(collection)).map(createOption).sort(compareOptions);
    },
    applyChanges: applySelectChanges,
};
